// HasProvider applies the HasEdge predicate on the "provider" edge.
func HasProvider() predicate.Sub2APIProviderProbeConfig {
	return predicate.Sub2APIProviderProbeConfig(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, ProviderTable, ProviderColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasProviderWith applies the HasEdge predicate on the "provider" edge with a given conditions (other predicates).
func HasProviderWith(preds ...predicate.Sub2APIProvider) predicate.Sub2APIProviderProbeConfig {
	return predicate.Sub2APIProviderProbeConfig(func(s *sql.Selector) {
		step := newProviderStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

